package com.ecole.gestion_scolaire.studentportal.controller; import com.ecole.gestion_scolaire.studentportal.dto.StudentPortalDtos.*; import com.ecole.gestion_scolaire.studentportal.service.StudentPortalService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/student-portal") @PreAuthorize("hasAuthority('PORTAIL_ELEVE_ACCEDER')") public class StudentPortalController{private final StudentPortalService s;public StudentPortalController(StudentPortalService s){this.s=s;}@GetMapping("/me")public Me me(){return s.me();}@GetMapping("/attendance")@PreAuthorize("hasAuthority('PORTAIL_ELEVE_PEDAGOGIE')")public List<Attendance> attendance(){return s.attendance();}@GetMapping("/timetable")@PreAuthorize("hasAuthority('PORTAIL_ELEVE_PEDAGOGIE')")public List<Timetable> timetable(){return s.timetable();}@GetMapping("/exercises")@PreAuthorize("hasAuthority('PORTAIL_ELEVE_PEDAGOGIE')")public List<Exercise> exercises(){return s.exercises();}@GetMapping("/grades")@PreAuthorize("hasAuthority('PORTAIL_ELEVE_PEDAGOGIE')")public List<Grade> grades(){return s.grades();}}
